class Solution {
  public List<Integer> findValidElements(int[] nums) {
    int n = nums.length;
    boolean[] valid = new boolean[n];
    int max = 0;
    for (int i = 0; i < n; i++) {
      if (nums[i] > max) valid[i] = true;
      max = Math.max(max, nums[i]);
    }
    max = 0;
    for (int i = n - 1; i >= 0; i--) {
      if (nums[i] > max) valid[i] = true;
      max = Math.max(max, nums[i]);
    }
    valid[0] = valid[n - 1] = true;
    List<Integer> ans = new ArrayList<>();
    for (int i = 0; i < n; i++) if (valid[i]) ans.add(nums[i]);
    return ans;
  }
}
